<script setup>
import {ref,watch,onUnmounted} from 'vue'
import {memberAccount,memberRpc} from './member-service.js'
import {formatMemberDate} from './member-table.js'
const detail=ref(null),error=ref('');let epoch=0
watch(()=>[memberAccount.value?.profile?.id,memberAccount.value?.profile?.services_revision],async ([id])=>{const e=++epoch;detail.value=null;if(!id)return;try{const data=await memberRpc('member_detail');if(e===epoch){detail.value=data;error.value=''}}catch{if(e===epoch)error.value='회원 상세 정보 확인에 실패했습니다.'}},{immediate:true});onUnmounted(()=>{++epoch})
function label(id){return detail.value?.catalog.find(c=>c.id===id)?.name||id.replace('ai:prestige','AI PM: 프레스티지').replace('msp:prestige','MS Project: 프레스티지').replace('pm:prestige','프로젝트 관리: 프레스티지')}
</script><template><section class="self-membership-detail"><h2>서비스 종류 · 회원 상세 정보</h2><p v-if="error" role="alert">{{error}}</p><template v-if="detail"><p>서비스 종류는 시스템 관리자가 설정합니다. 회원은 조회만 할 수 있습니다.</p><ul class="self-service-badges"><li v-for="code in detail.services" :key="code">{{label(code)}}</li></ul><p v-if="detail.requested_services.length">가입 시 신청한 서비스: {{detail.requested_services.map(label).join(', ')}}</p><dl><dt>가입일(KST)</dt><dd>{{formatMemberDate(detail.activity.joined_at)}}</dd><dt>마지막 로그인(KST)</dt><dd>{{detail.activity.last_sign_in_at?formatMemberDate(detail.activity.last_sign_in_at):'로그인 기록 없음'}}</dd><dt>등록한 이북 / 삭제</dt><dd>{{detail.activity.ebook_count}} / {{detail.activity.deleted_ebook_count}}건</dd></dl><h3>가입 답변</h3><dl v-if="detail.answers"><template v-for="(value,key) in detail.answers" :key="key"><dt>{{key}}</dt><dd>{{value||'미입력'}}</dd></template></dl><p v-else>가입 당시 답변 기록이 없습니다. 현재 회원정보는 아래에서 확인하실 수 있습니다.</p></template></section></template><style scoped>.self-membership-detail{border:1px solid #d7e2ef;border-radius:12px;padding:24px;margin:0 0 28px}.self-membership-detail h2{font-size:22px;font-weight:750;margin:0 0 16px}.self-membership-detail h3{font-size:17px;font-weight:700;margin:22px 0 12px}.self-membership-detail p{line-height:1.7;margin:12px 0}.self-service-badges{display:flex;flex-wrap:wrap;gap:9px;list-style:none;padding:0;margin:18px 0}.self-service-badges li{padding:7px 12px;border-radius:7px;background:#e8f1fd;color:#195b9c;font-weight:650}.self-membership-detail dl{display:grid;grid-template-columns:150px minmax(0,1fr);gap:10px;font-size:14px}.self-membership-detail dt{font-weight:650}.self-membership-detail dd{margin:0;overflow-wrap:anywhere}</style>
